/**
 * The website's Cloudflare Worker entry (wrangler.jsonc `main`): OpenNext's generated handler, served through Sentry's
 * `withSentry` when the build has a Sentry DSN, and as it is otherwise (lib/observability/sentry-worker.ts). wrangler
 * bundles this file at deploy time with the `.open-next/` output of `npm run cf:build`.
 */
import { env } from "cloudflare:workers";
import { sentryWorkerEntry } from "./src/lib/observability/sentry-worker";
// @ts-expect-error -- untyped JavaScript generated by `opennextjs-cloudflare build` (absent before a build)
import openNextHandler from "./.open-next/worker.js";
// @ts-expect-error -- the build's env files as OpenNext compiles them for the Worker (generated, untyped)
import * as nextEnv from "./.open-next/cloudflare/next-env.mjs";

// Everything else OpenNext's entry exports (its Durable Object classes), so wrangler sees the same module.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export * from "./.open-next/worker.js";

// The env files' values for the mode OpenNext's own init reads them for.
const mode = typeof env.NEXTJS_ENV === "string" ? env.NEXTJS_ENV : "production";
const buildEnv = (nextEnv as Record<string, unknown>)[mode];

export default sentryWorkerEntry(openNextHandler as object, buildEnv);
